mapper.select:
SELECT T.SERIALNO, FUNDACCT, TRADEACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, APKIND, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, INVTP, INVNM, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, IDTP, IDNO, TELNO, MOBILENO, ADDR, POSTCODE, EMAIL, FAXNO, DELIVERTYPE, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, MELONMD, WORKDATE, APPLYST, APDT, APTM, HOMETEL, OFFICETEL, (CASE WHEN REGIONCODE = '0001' THEN '网下' WHEN REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, REGIONCODE, NETPOINT, CUSTTP, INSTREPRNAME, INSTREPRIDTP, INSTREPRIDNO, BROKERNAME, BROKERIDTP, BROKERIDNO, BROKEROFFICETEL, BROKERFAX, CHECKER, OPID, IBF_GET_PARAMNAME('SYSTEM','CHKFLAG',CHKFLAG) CHKFLAG_NAME, CHKFLAG, ACCOUNTABBR, CUSTABBRCODE, CUSTINSTREPRCODE, (CONCAT(IBF_GET_PARAMNAME('DSCUSTGROUP','FIRSTGROUP',CUSTABBRCODE),'-') || (SELECT PMNM FROM PARAMETER WHERE PMST = 'DSCUSTGROUP' AND PMKY = 'SECONDGROUP' AND PMV1 = CUSTABBRCODE AND PMCO = CUSTINSTREPRCODE)) INVNAME, APPNO FROM V_APPFDACTODAY T WHERE 1 = 1
AND TRIM(FUNDACCT) = #{sp.fundacct}
AND IDNO = #{sp.idno}
AND INVNM LIKE '%'||#{sp.invnm}||'%'
AND WORKDATE = #{sp.appDate}
AND APKIND = #{sp.apkind}
AND TANO = #{sp.tano}
AND NETPOINT = #{sp.netpoint}
AND REGIONCODE = #{sp.qway}
ORDER BY INVNM,CONCAT(APDT,APTM),APPNO ASC

SELECT T.SERIALNO, FUNDACCT, TRADEACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, APKIND, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, INVTP, INVNM, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, IDTP, IDNO, TELNO, MOBILENO, ADDR, POSTCODE, EMAIL, FAXNO, DELIVERTYPE, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, MELONMD, WORKDATE, APPLYST, APDT, APTM, HOMETEL, OFFICETEL, (CASE WHEN REGIONCODE = '0001' THEN '网下' WHEN REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, REGIONCODE, NETPOINT, CUSTTP, INSTREPRNAME, INSTREPRIDTP, INSTREPRIDNO, BROKERNAME, BROKERIDTP, BROKERIDNO, BROKEROFFICETEL, BROKERFAX, CHECKER, OPID, IBF_GET_PARAMNAME('SYSTEM','CHKFLAG',CHKFLAG) CHKFLAG_NAME, CHKFLAG, ACCOUNTABBR, CUSTABBRCODE, CUSTINSTREPRCODE, (CONCAT(IBF_GET_PARAMNAME('DSCUSTGROUP','FIRSTGROUP',CUSTABBRCODE),'-') || (SELECT PMNM FROM PARAMETER WHERE PMST = 'DSCUSTGROUP' AND PMKY = 'SECONDGROUP' AND PMV1 = CUSTABBRCODE AND PMCO = CUSTINSTREPRCODE)) INVNAME, APPNO FROM V_APPFDACTODAY T WHERE 1 = 1
AND TRIM(FUNDACCT) = #{sp.fundacct}
AND IDNO = #{sp.idno}
AND INVNM LIKE '%'||#{sp.invnm}||'%'
AND WORKDATE = #{sp.appDate}
AND APKIND = #{sp.apkind}
AND TANO = #{sp.tano}
AND NETPOINT = #{sp.netpoint}
AND REGIONCODE = #{sp.qway}
ORDER BY INVNM,CONCAT(APDT,APTM),APPNO ASC

			SELECT COUNT(*) 
		    		FROM V_APPFDACTODAY
			   		WHERE 1=1

				  		 AND TRIM(FUNDACCT) = #{sp.fundacct}


				  		 AND IDNO = #{sp.idno}


				  		 AND INVNM LIKE '%'||#{sp.invnm}||'%' 


				  		 AND WORKDATE = #{sp.appDate}


