SELECT ACKDT, ACKNO, T.SERIALNO, APPNO, FUNDACCT, TRADEACCO, INVNM, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, INVTP, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, IDTP, IDNO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, APKIND, NULL AS CLEARDT, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, MELONMD, MULTIACCTFLAG, RETCODE, RETMSG, NETPOINT FROM V_T_ACKFDACBLOTTER T WHERE 1=1
