SELECT S.ACKDT, S.ACKNO, S.RETCODE, S.RETMSG, S.SERIALNO, S.APPNO, S.FUNDACCT, S.TRADEACCO, S.INVNM, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, S.INVTP, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, S.IDTP, S.IDNO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, S.APKIND, S.CLEARDT, S.APPLYST, S.NETPOINT, S.MELONMD, S.MULTIACCTFLAG FROM S_ACKFDACBLOTTER S, TRADEACCOINFO T WHERE 1 = 1 AND S.TRADEACCO = T.TRADEACCO
AND TRIM(S.FUNDACCT) = #{sp.fundacct}
AND S.IDNO = #{sp.idno}
AND S.INVNM LIKE '%'||#{sp.invnm}||'%'
