AND T.REGIONCODE = #{sp.qway}
AND S.NETPOINT = #{sp.netpoint}
ORDER BY S.INVNM,S.ACKDT,S.ACKNO ASC

	 SELECT COUNT(*)
	    FROM S_ACKFDACBLOTTER S,
	         TRADEACCOINFO T
	         WHERE 1 = 1
             AND S.TRADEACCO = T.TRADEACCO

  		 AND TRIM(S.FUNDACCT) = #{sp.fundacct}


  		 AND S.IDNO = #{sp.idno}


  		 AND S.INVNM LIKE '%'||#{sp.invnm}||'%' 


