SELECT DISTINCT S.SERIALNO, S.APPNO, S.FUNDACCT, S.NETPOINT, S.TRADEACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, S.APKIND, S.CUSTTP, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, S.INVTP, S.INVNM, S.ACCOUNTABBR, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, S.IDTP, S.IDNO, S.INSTREPRNAME, S.INSTREPRIDTP, S.INSTREPRIDNO, S.TELNO, S.MOBILENO, S.ADDR, S.POSTCODE, S.EMAIL, S.FAXNO, S.BROKERNAME, S.BROKERIDTP, S.BROKERIDNO, S.DELIVERTYPE, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, S.MELONMD, S.OPID, S.APDT, (CASE WHEN S.REGIONCODE = '0001' THEN '网下' WHEN S.REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, S.REGIONCODE, S.HOMETEL, S.OFFICETEL, S.BROKEROFFICETEL, S.BROKERFAX, S.CHECKER, IBF_GET_PARAMNAME('DS','CHKFLAG',CHKFLAG) CHKFLAG_NAME, S.CHKFLAG, (CONCAT(IBF_GET_PARAMNAME('DSCUSTGROUP','FIRSTGROUP',DS.CUSTABBRCODE),'-') || (SELECT PMNM FROM PARAMETER WHERE PMST = 'DSCUSTGROUP' AND PMKY = 'SECONDGROUP' AND PMV1 = DS.CUSTABBRCODE AND PMCO = DS.CUSTINSTREPRCODE)) INVNAME, DS.CUSTABBRCODE, DS.CUSTINSTREPRCODE FROM H_APPFDACBLOTTER S, DS_CUSTCLASSINFO DS WHERE 1 = 1 AND S.CUSTNO = DS.CUSTNO(+)
AND S.APDT >= #{sp.startDate}
AND S.APDT <= #{sp.endDate}
AND TRIM(S.FUNDACCT) = #{sp.fundacct}
AND S.IDNO = #{sp.idno}
AND S.INVNM LIKE '%'||#{sp.invnm}||'%'
AND S.APKIND = #{sp.apkind}
AND S.TANO = #{sp.tano}
AND S.REGIONCODE = #{sp.qway}
AND S.NETPOINT = #{sp.netpoint}
ORDER BY S.INVNM,S.APDT,S.APPNO ASC

SELECT DISTINCT S.SERIALNO, S.APPNO, S.FUNDACCT, S.NETPOINT, S.TRADEACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, S.APKIND, S.CUSTTP, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, S.INVTP, S.INVNM, S.ACCOUNTABBR, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, S.IDTP, S.IDNO, S.INSTREPRNAME, S.INSTREPRIDTP, S.INSTREPRIDNO, S.TELNO, S.MOBILENO, S.ADDR, S.POSTCODE, S.EMAIL, S.FAXNO, S.BROKERNAME, S.BROKERIDTP, S.BROKERIDNO, S.DELIVERTYPE, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, S.MELONMD, S.OPID, S.APDT, (CASE WHEN S.REGIONCODE = '0001' THEN '网下' WHEN S.REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, S.REGIONCODE, S.HOMETEL, S.OFFICETEL, S.BROKEROFFICETEL, S.BROKERFAX, S.CHECKER, IBF_GET_PARAMNAME('DS','CHKFLAG',CHKFLAG) CHKFLAG_NAME, S.CHKFLAG, (CONCAT(IBF_GET_PARAMNAME('DSCUSTGROUP','FIRSTGROUP',DS.CUSTABBRCODE),'-') || (SELECT PMNM FROM PARAMETER WHERE PMST = 'DSCUSTGROUP' AND PMKY = 'SECONDGROUP' AND PMV1 = DS.CUSTABBRCODE AND PMCO = DS.CUSTINSTREPRCODE)) INVNAME, DS.CUSTABBRCODE, DS.CUSTINSTREPRCODE FROM H_APPFDACBLOTTER S, DS_CUSTCLASSINFO DS WHERE 1 = 1 AND S.CUSTNO = DS.CUSTNO(+)
AND S.APDT >= #{sp.startDate}
