SELECT COUNT(*)
   FROM H_APPFDACBLOTTER S,
        DS_CUSTCLASSINFO DS
   WHERE 1 = 1
  		 AND S.CUSTNO = DS.CUSTNO(+)

 		 AND S.APDT >= #{sp.startDate}


