SELECT H.ACKDT, H.ACKNO, H.RETCODE, H.RETMSG, H.SERIALNO, H.NETPOINT, H.APPNO, H.FUNDACCT, H.TRADEACCO, H.INVNM, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, H.INVTP, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, H.IDTP, H.IDNO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, H.APKIND, H.CLEARDT, H.APPLYST, IBF_GET_PARAMNAME('SYSTEM','MELONMD',H.MELONMD) MELONMD_NAME, H.MELONMD, H.MULTIACCTFLAG, (CASE WHEN T.REGIONCODE = '0001' THEN '网下' WHEN T.REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, T.REGIONCODE, DS.BROKERNAME, DS.BROKEROFFICETEL, DS.BROKERFAX, (CONCAT(IBF_GET_PARAMNAME('DSCUSTGROUP','FIRSTGROUP',DC.CUSTABBRCODE),'-') || (SELECT PMNM FROM PARAMETER WHERE PMST = 'DSCUSTGROUP' AND PMKY = 'SECONDGROUP' AND PMV1 = DC.CUSTABBRCODE AND PMCO = DC.CUSTINSTREPRCODE)) INVNAME, DC.CUSTABBRCODE, DC.CUSTINSTREPRCODE FROM HS_ACKFDACBLOTTER H, TRADEACCOINFO T, ( SELECT * FROM DS_CUSTINFOADD WHERE MAINBROKERFLAG ='1' AND INFOFLAG ='B' ) DS, DS_CUSTCLASSINFO DC WHERE 1 = 1 AND H.CUSTNO = DS.CUSTNO(+) AND H.CUSTNO = DC.CUSTNO(+) AND H.TRADEACCO = T.TRADEACCO
AND H.ACKDT >= #{sp.startDate}
AND H.ACKDT <= #{sp.endDate}
AND TRIM(H.FUNDACCT) = #{sp.fundacct}
AND H.NETPOINT = #{sp.netpoint}
AND H.IDNO = #{sp.idno}
AND H.INVNM LIKE '%'||#{sp.invnm}||'%'
AND H.APKIND = #{sp.apkindack}
AND H.TANO = #{sp.tano}
AND T.REGIONCODE = #{sp.qway}
ORDER BY H.INVNM,H.ACKDT,H.ACKNO ASC

SELECT H.ACKDT, H.ACKNO, H.RETCODE, H.NETPOINT, H.RETMSG, H.SERIALNO, H.APPNO, H.FUNDACCT, H.TRADEACCO, H.INVNM, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, H.INVTP, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, H.IDTP, H.IDNO, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, H.APKIND, H.CLEARDT, H.APPLYST, IBF_GET_PARAMNAME('SYSTEM','MELONMD',H.MELONMD) MELONMD_NAME, H.MELONMD, H.MULTIACCTFLAG, (CASE WHEN T.REGIONCODE = '0001' THEN '网下' WHEN T.REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, T.REGIONCODE, DS.BROKERNAME, DS.BROKEROFFICETEL, DS.BROKERFAX, DC.CUSTABBRCODE, DC.CUSTINSTREPRCODE, (CONCAT(IBF_GET_PARAMNAME('DSCUSTGROUP','FIRSTGROUP',DC.CUSTABBRCODE),'-') || (SELECT PMNM FROM PARAMETER WHERE PMST = 'DSCUSTGROUP' AND PMKY = 'SECONDGROUP' AND PMV1 = DC.CUSTABBRCODE AND PMCO = DC.CUSTINSTREPRCODE)) INVNAME FROM HS_ACKFDACBLOTTER H, TRADEACCOINFO T, ( SELECT * FROM DS_CUSTINFOADD WHERE MAINBROKERFLAG ='1' AND INFOFLAG ='B' ) DS, DS_CUSTCLASSINFO DC WHERE 1 = 1 AND H.CUSTNO = DS.CUSTNO(+) AND H.CUSTNO = DC.CUSTNO(+) AND H.TRADEACCO = T.TRADEACCO
AND H.ACKDT >= #{sp.startDate}
AND H.ACKDT <= #{sp.endDate}
AND H.NETPOINT = #{sp.netpoint}
AND TRIM(H.FUNDACCT) = #{sp.fundacct}
AND H.IDNO = #{sp.idno}
AND H.INVNM LIKE '%'||#{sp.invnm}||'%'
AND H.APKIND = #{sp.apkindack}
AND H.TANO = #{sp.tano}
AND T.REGIONCODE = #{sp.qway}
ORDER BY H.INVNM,H.ACKDT,H.ACKNO ASC

		  SELECT  COUNT(*)
	    	 FROM HS_ACKFDACBLOTTER H,
	         TRADEACCOINFO T,
	         (
	           SELECT *
	             FROM DS_CUSTINFOADD
	            WHERE MAINBROKERFLAG ='1'
	              AND INFOFLAG ='B'
	         ) DS,
	         DS_CUSTCLASSINFO DC
	         WHERE 1 = 1 
	         AND H.CUSTNO = DS.CUSTNO(+)
	         AND H.CUSTNO = DC.CUSTNO(+)    
	         AND H.TRADEACCO = T.TRADEACCO

  		 AND H.ACKDT >= #{sp.startDate}


  		 AND H.ACKDT <= #{sp.endDate}


  		 AND TRIM(H.FUNDACCT) = #{sp.fundacct}


  		 AND H.NETPOINT = #{sp.netpoint}


  		 AND H.IDNO = #{sp.idno}


  		 AND H.INVNM LIKE '%'||#{sp.invnm}||'%' 


  		 AND H.APKIND = #{sp.apkindack}


  		 AND H.TANO = #{sp.tano}


  		 AND T.REGIONCODE = #{sp.qway}

    ORDER BY H.INVNM,H.ACKDT,H.ACKNO ASC

SELECT DISTINCT H.SERIALNO APDT, FUNDACCT, INVNM, NETPOINT, IBF_GET_PARAMNAME('SYSTEM','IDTP',IDTP) IDTP_NAME, IDTP, IDNO, BANKNO, BANKLONGNAME, BANKACNM, BANKACCO, MOBILENO, ADDR, POSTCODE, EMAIL, FAXNO, HOMETEL, OFFICETEL, DELIVERTYPE, BROKERNAME, BROKERIDTP, BROKERIDNO, BROKEROFFICETEL, BROKERFAX, BROKERVALIDDATE, BROKERMOBILE, BROKEREMAIL, BROKERNATION, INSTREPRNAME, INSTREPRIDTP, INSTREPRIDNO, INSTREPRNATION, INSTREPDATE, PRINCIPALNAME, PRINCIPALNATION, PRINCIPALTYPE, PRINCIPALNO, PRINCIPALVALIDATE, TRADEACCO, APKIND, CUSTTP, INVTP, OPID, REGIONCODE, APPNO FROM H_APPFDACBLOTTER H WHERE 1 = 1 AND REGIONCODE = '0001' AND (APKIND = '003' OR APKIND = '0B1')
AND APDT >= #{sp.startDate}
AND APDT <= #{sp.endDate}
AND NETPOINT = #{sp.netpoint}
ORDER BY INVNM,APDT,APPNO ASC

	  SELECT COUNT(*)
	    FROM H_APPFDACBLOTTER
	    WHERE 1 = 1 
	     AND REGIONCODE = '0001'   
	     AND (APKIND = '003' OR APKIND = '0B1')

  		 	 AND APDT >= #{sp.startDate}


	  		 AND APDT <= #{sp.endDate}


	  		 AND NETPOINT = #{sp.netpoint}

	    ORDER BY INVNM,APDT,APPNO ASC
